data.document:
query MexFetchNewsletterDirectoryCategoriesPreviewJobQuery($fetch_status_metadata, $input) {
  id
  text
  update_time
  xwa2_newsletters_directory_category_preview {
    result {
      category
      category_title
      newsletters {
        thread_metadata {
          creation_time
          invite
          handle
          subscribers_count
          name {
            description {
              picture {
                direct_path
                type
                verification
                status_metadata {
                  last_status_server_id
                  last_status_sent_time
                }
              }
            }
          }
        }
      }
    }
  }
}
